"""Kaggle kernel for the project benchmark with a larger model (generated by lane.py).

lane.py replaces the JOB line below with the job and pushes this file as a private script
kernel on 2 x T4. On Kaggle it:

1. records the hardware and verifies the bundle against bundle-manifest.json;
2. builds the locked environment with uv (Python 3.11, uv.lock without dev packages) and
   adds llama-cpp-python 0.3.4 from its prebuilt CUDA 12.4 wheel index;
3. downloads the job's GGUF model at a pinned revision and checks its SHA-256;
4. runs the static arm and the model arm of scripts/project_benchmark_model_arm.py on the
   job's split as an unprivileged user (the project test runner drops root to "nobody",
   whose access to the runner's private temporary folders the frozen code does not set up);
5. writes logs, status.json and outputs-manifest.json to /kaggle/working.
"""

import hashlib
import json
import os
import platform
import shutil
import subprocess
import sys
import time
import traceback
import zipfile
from datetime import UTC, datetime
from pathlib import Path

JOB = {}  # replaced by lane.py

MODELS = {
    "14b": {
        "repo": "bartowski/Qwen2.5-Coder-14B-Instruct-GGUF",
        "revision": "5b379ec4bf71bafecb5f9081ad28b19939128988",
        "file": "Qwen2.5-Coder-14B-Instruct-Q4_K_M.gguf",
        "sha256": "2946d28c9e1bb2bcae6d42e8678863a31775df6f740315c7d7e6d6b6411f5937",
    },
    "32b": {
        "repo": "bartowski/Qwen2.5-Coder-32B-Instruct-GGUF",
        "revision": "40b525506a4f98ed425882fa6dfc90cc8139065e",
        "file": "Qwen2.5-Coder-32B-Instruct-Q4_K_M.gguf",
        "sha256": "8e2fd78ff55e7cdf577fda257bac2776feb7d73d922613caf35468073807e815",
    },
}
LLAMA_INDEX = "https://abetlen.github.io/llama-cpp-python/whl/cu124"
WORK = Path("/kaggle/working")
TMP = Path("/tmp/grad")
REPO = TMP / "repo"
MODELS_DIR = TMP / "models"
OUT = TMP / "out"
LOGS = WORK / "logs"
USER = "bench"
STATUS = {"job": JOB, "started_at": datetime.now(UTC).isoformat(timespec="seconds"), "steps": []}


def log(message: str) -> None:
    line = f"[{datetime.now(UTC):%H:%M:%S}] {message}"
    print(line, flush=True)
    with open(LOGS / "kernel.log", "a", encoding="utf-8") as handle:
        handle.write(line + "\n")


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def run(command: list[str], name: str, cwd: Path | None = None, env: dict | None = None) -> int:
    log(f"$ {' '.join(command)}")
    started = time.time()
    with open(LOGS / f"{name}.log", "w", encoding="utf-8") as handle:
        process = subprocess.run(
            command, cwd=cwd, env=env, stdout=handle, stderr=subprocess.STDOUT, text=True
        )
    log(f"{name}: exit {process.returncode} after {time.time() - started:.1f} s")
    if process.returncode != 0:
        tail = (LOGS / f"{name}.log").read_text(encoding="utf-8", errors="replace")[-3000:]
        log(f"{name} log tail:\n{tail}")
    return process.returncode


class Step:
    def __init__(self, name: str) -> None:
        self.name = name

    def __enter__(self):
        self.started = time.time()
        log(f"== {self.name}")
        return self

    def __exit__(self, kind, value, tb):
        entry = {"step": self.name, "seconds": round(time.time() - self.started, 1)}
        entry["ok"] = kind is None
        if kind is not None:
            entry["error"] = f"{kind.__name__}: {value}"[:2000]
            log("".join(traceback.format_exception(kind, value, tb))[-3000:])
        STATUS["steps"].append(entry)
        return False


def hardware() -> dict:
    info = {"python": sys.version.split()[0], "platform": platform.platform()}
    info["cpu_count"] = os.cpu_count()
    try:
        info["ram_total_kb"] = int(Path("/proc/meminfo").read_text().split()[1])
    except (OSError, IndexError, ValueError):
        info["ram_total_kb"] = None
    smi = subprocess.run(
        [
            "nvidia-smi",
            "--query-gpu=name,memory.total,driver_version,compute_cap",
            "--format=csv,noheader",
        ],
        capture_output=True,
        text=True,
    )
    info["nvidia_smi"] = smi.stdout.strip()
    return info


def locate_bundle() -> None:
    manifests = sorted(Path("/kaggle/input").rglob("bundle-manifest.json"))
    zips = sorted(Path("/kaggle/input").rglob("bundle.zip"))
    if REPO.exists():
        shutil.rmtree(REPO)
    if manifests:
        shutil.copytree(manifests[0].parent, REPO)
    elif zips:
        REPO.mkdir(parents=True)
        with zipfile.ZipFile(zips[0]) as archive:
            archive.extractall(REPO)
    else:
        raise FileNotFoundError("no bundle under /kaggle/input")
    manifest = json.loads((REPO / "bundle-manifest.json").read_text(encoding="utf-8"))
    bad = [p for p, sha in manifest["files"].items() if sha256_file(REPO / p) != sha]
    if bad:
        raise ValueError(f"bundle files do not match the manifest: {bad[:10]}")
    if manifest["bundle_sha256"] != JOB["bundle_sha256"]:
        raise ValueError("the bundle is not the one the job expects; the dataset is stale")
    STATUS["bundle"] = {k: manifest[k] for k in ("bundle_sha256", "git_head", "git_dirty")}


def venv_python() -> Path:
    return REPO / ".venv" / "bin" / "python"


def install() -> None:
    if run([sys.executable, "-m", "pip", "install", "--quiet", "uv==0.12.0"], "pip-uv") != 0:
        raise RuntimeError("installing uv failed")
    uv = [sys.executable, "-m", "uv"]
    env = dict(os.environ, UV_PYTHON_INSTALL_DIR=str(TMP / "python"))
    if run([*uv, "sync", "--frozen", "--no-dev"], "uv-sync", cwd=REPO, env=env) != 0:
        raise RuntimeError("uv sync failed")
    llama = [
        *uv,
        "pip",
        "install",
        "--python",
        str(venv_python()),
        "--no-deps",
        "--index-strategy",
        "unsafe-best-match",
        "--extra-index-url",
        LLAMA_INDEX,
        "llama-cpp-python==0.3.4",
        "diskcache==5.6.3",
        "numpy<2.3",
        "typing-extensions",
        "jinja2",
        "markupsafe",
    ]
    if run(llama, "llama-install", cwd=REPO, env=env) != 0:
        raise RuntimeError("installing llama-cpp-python failed")
    probe = subprocess.run(
        [
            str(venv_python()),
            "-I",
            "-c",
            "import json, llama_cpp; print(json.dumps({'llama_cpp': llama_cpp.__version__, "
            "'gpu_offload': bool(llama_cpp.llama_supports_gpu_offload())}))",
        ],
        capture_output=True,
        text=True,
    )
    log(f"llama probe: {probe.stdout.strip()} {probe.stderr[-500:]}")
    STATUS["llama"] = json.loads(probe.stdout) if probe.returncode == 0 else None
    if not (STATUS["llama"] or {}).get("gpu_offload"):
        raise RuntimeError("llama-cpp-python has no GPU offload")


def download_model() -> Path:
    spec = MODELS[JOB["model"]]
    os.environ["HF_HUB_DISABLE_XET"] = "1"
    from huggingface_hub import hf_hub_download

    folder = MODELS_DIR / JOB["model"]
    path = Path(
        hf_hub_download(
            spec["repo"], spec["file"], revision=spec["revision"], local_dir=str(folder)
        )
    )
    digest = sha256_file(path)
    if digest != spec["sha256"]:
        raise ValueError(f"{spec['file']} sha256 {digest} != {spec['sha256']}")
    STATUS["model"] = {**spec, "verified": True}
    return path


def model_config(path: Path) -> Path:
    spec = MODELS[JOB["model"]]
    config = {
        "python": str(venv_python()),
        "model_dir": str(path.parent),
        "model_id": spec["repo"],
        "model_revision": spec["revision"],
        "gguf_file": spec["file"],
        "gguf_sha256": spec["sha256"],
        "context_tokens": 8192,
        "gpu_layers": -1,
        "device": "cuda",
        "dtype": "float16",
        "load_timeout_s": 1800,
    }
    target = TMP / "model.json"
    target.write_text(json.dumps(config, indent=2), encoding="utf-8")
    shutil.copy(target, LOGS / "model.json")
    return target


def benchmark(config: Path) -> None:
    if subprocess.run(["id", USER], capture_output=True).returncode != 0:
        subprocess.run(["useradd", "--create-home", USER], check=True)
    OUT.mkdir(parents=True, exist_ok=True)
    subprocess.run(["chmod", "-R", "a+rX", str(TMP)], check=True)
    subprocess.run(["chown", "-R", f"{USER}:{USER}", str(OUT)], check=True)
    # Kaggle's environment (CUDA library paths included) with the user's home and the
    # locked environment first on PATH; the model worker inherits it.
    env = dict(
        os.environ,
        PATH=f"{venv_python().parent}:{os.environ.get('PATH', '/usr/bin:/bin')}",
        HOME=f"/home/{USER}",
        PYTHONIOENCODING="utf-8",
    )
    as_user = ["runuser", "-u", USER, "--"]
    python = str(venv_python())
    split = JOB["split"]
    projects = [arg for name in JOB.get("projects", []) for arg in ("--project", name)]
    static = [python, "scripts/project_benchmark.py", "run", "--split", split]
    static += ["--arm", "static", "--out", str(OUT / f"{split}-static"), *projects]
    if split in ("test", "test2", "test3"):
        static += ["--model-config", str(config)]  # the static arm uses no model
        static += ["--allow-unfrozen"]  # only the model differs; recorded in run.json
    run([*as_user, *static], "bench-static", cwd=REPO, env=env)
    arm = [python, "scripts/project_benchmark_model_arm.py", "--split", split]
    arm += ["--name", JOB["model"], "--model-config", str(config)]
    arm += ["--out", str(OUT / f"{split}-full-{JOB['model']}"), *projects]
    code = run([*as_user, *arm], "bench-model", cwd=REPO, env=env)
    if code != 0:
        raise RuntimeError("the model arm failed")


def finish(ok: bool) -> None:
    if OUT.exists():
        shutil.copytree(OUT, WORK / "bench", dirs_exist_ok=True)
    STATUS["finished_at"] = datetime.now(UTC).isoformat(timespec="seconds")
    STATUS["ok"] = ok
    (WORK / "status.json").write_text(json.dumps(STATUS, indent=2), encoding="utf-8")
    files = {}
    for path in sorted(WORK.rglob("*")):
        if path.is_file() and path.name != "outputs-manifest.json":
            files[path.relative_to(WORK).as_posix()] = sha256_file(path)
    (WORK / "outputs-manifest.json").write_text(json.dumps(files, indent=2), encoding="utf-8")


def main() -> int:
    LOGS.mkdir(parents=True, exist_ok=True)
    TMP.mkdir(parents=True, exist_ok=True)
    ok = True
    try:
        if JOB.get("model") not in MODELS or JOB.get("split") not in (
            "dev",
            "test",
            "test2",
            "test3",
        ):
            raise ValueError(f"bad job: {JOB}")
        with Step("hardware"):
            STATUS["hardware"] = hardware()
        with Step("bundle"):
            locate_bundle()
        with Step("install"):
            install()
        with Step("model"):
            path = download_model()
        with Step("benchmark"):
            benchmark(model_config(path))
    except Exception:  # recorded in status.json; the kernel then errors
        ok = False
    finish(ok)
    return 0 if ok else 1


if __name__ == "__main__":
    raise SystemExit(main())
